def solution(data):
    df_sales = data.get('So_chi_tiet_ban_hang')
    if df_sales is None:
        raise DataNotFoundError("Không tìm thấy bảng bán hàng")

    cols = df_sales.columns.tolist()
    d_c = next((c for c in cols if any(k in str(c).lower() for k in ['ngày', 'date', 'thời gian'])), None)
    if d_c:
        df_sales['clean_date'] = clean_date(df_sales[d_c])
        mask = (df_sales['clean_date'].dt.year == 2026) & (df_sales['clean_date'].dt.month == 4)
        df_sales = df_sales[mask]

    item_col = next((c for c in cols if any(k in str(c).lower() for k in ['hàng', 'tên món', 'tên hàng', 'sản phẩm', 'mặt hàng'])), None)
    if item_col:
        df_sales = df_sales.groupby(item_col).filter(lambda x: len(x) >= 84)

    return len(df_sales[item_col].unique())
